def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most common color is the background; uniform lines of other
    # colors are separators. Uniform background lines are not separators.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    divider_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    divider_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    def sections(length, dividers):
        result = []
        start = 0
        for p in dividers:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < length:
            result.append((start, length))
        return result

    row_sections = sections(h, divider_rows)
    col_sections = sections(w, divider_cols)

    # Find the section containing the most non-background cells.
    source = None
    most_marks = -1
    for ri, (r0, r1) in enumerate(row_sections):
        for ci, (c0, c1) in enumerate(col_sections):
            marks = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            if marks > most_marks:
                source = (ri, ci)
                most_marks = marks

    if source is None or most_marks == 0:
        return [row[:] for row in grid]

    sri, sci = source
    sr0, sr1 = row_sections[sri]
    sc0, sc1 = col_sections[sci]
    out = [row[:] for row in grid]

    # Repeat the marked pattern from the source section in every section.
    for ri, (r0, r1) in enumerate(row_sections):
        for ci, (c0, c1) in enumerate(col_sections):
            if (ri, ci) == source:
                continue
            for dr in range(min(sr1 - sr0, r1 - r0)):
                for dc in range(min(sc1 - sc0, c1 - c0)):
                    value = grid[sr0 + dr][sc0 + dc]
                    if value != background:
                        out[r0 + dr][c0 + dc] = value

    return out
